package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.articles.JdbcCatalogVersionSourceFacts;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

/** Real source rows and raw digests, not source admission or a permanent version business decision. */
class CatalogVersionSourceFactsTest extends CatalogVersionQualificationTest {
    JdbcCatalogVersionSourceFacts storage(){return new JdbcCatalogVersionSourceFacts(f.source,f.category);}
    JdbcCatalogVersionSourceFacts.Snapshot capture(){var tx=new TransactionTemplate(f.tx);tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);return tx.execute(s->storage().capture("fictional-current-item"));}
    @Test void FourCategoryNativeMemberConfigurationAndPayloadFingerprintsRecheckUnderTheOriginalWriter(){for(String category:List.of("agent","skill","workflow","model")){initialize(category,false);var original=capture();assertEquals("fictional-run",original.scalars().get(1));assertEquals("fictional-source",original.scalars().get(3));assertEquals("fictional-current-source-item",original.scalars().get(17));assertTrue(original.body().bytes()>0);assertTrue(original.config().bytes()>0);var tx=new TransactionTemplate(f.tx);tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);assertEquals(original,tx.execute(s->storage().lockAndRead("fictional-current-item")));assertThrows(UnsupportedOperationException.class,()->original.scalars().clear());assertFalse(original.toString().contains("fictional"));assertEquals(1,f.sends);}}
    @Test void RawBodyOrConfigurationChangedWithoutAnyRevisionCannotRemainTheSameProof(){var original=capture();f.jdbc.update("UPDATE source_run_items SET evidence_json=? WHERE id='fictional-current-item'","{\"fictional_changed\":true}");assertNotEquals(original,capture());initialize("agent",false);original=capture();f.jdbc.update("UPDATE source_runs SET config_snapshot_json=?","{\"parser_version\":\"fictional-parser-v1\",\"fictional_changed\":true}");assertNotEquals(original,capture());}
    @Test void AliasRoleTransactionAndMetadataChangesCannotBeSilentlyAccepted(){var original=capture();f.jdbc.update("UPDATE source_run_items SET source_item_id='fictional-later-source-item',revision=revision+1,state='ready'");assertNotEquals(original,capture());f.jdbc.update("UPDATE source_run_items SET source_id='fictional-foreign'");assertThrows(RuntimeException.class,this::capture);initialize("agent",false);assertThrows(RuntimeException.class,()->storage().capture("fictional-current-item"));var tx=new TransactionTemplate(f.tx);assertThrows(RuntimeException.class,()->tx.execute(s->storage().capture("fictional-current-item")));tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);assertThrows(RuntimeException.class,()->tx.execute(s->storage().lockAndRead("fictional-current-item")));assertThrows(RuntimeException.class,()->tx.execute(s->new JdbcCatalogVersionSourceFacts(f.source,"skill").capture("fictional-current-item")));assertThrows(RuntimeException.class,()->tx.execute(s->storage().capture("fictional-absent")));}
    @Test void NativeOverwideBodyOrConfigurationRejectBeforeAnyWideTextEntersTheResult(){f.jdbc.update("UPDATE source_run_items SET evidence_json=? WHERE id='fictional-current-item'","{\"fictional_long\":\""+"x".repeat(262144)+"\"}");assertThrows(JdbcCatalogVersionSourceFacts.CapacityRejected.class,this::capture);initialize("agent",false);f.jdbc.update("UPDATE source_runs SET config_snapshot_json=?","{\"fictional_long\":\""+"x".repeat(65536)+"\"}");assertThrows(JdbcCatalogVersionSourceFacts.CapacityRejected.class,this::capture);}
}
